import{_ as o,C as t,c as s,o as n,aj as l,G as i,w as h}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/Targets-01-Chart.webp",d="/sk/images/Targets-02-Chart.webp",T=JSON.parse('{"title":"Targets","description":"","frontmatter":{"outline":"deep","prev":{"text":"Stop Placement","link":"/trading-with-pav/stop-placement"},"next":{"text":"Entry","link":"/trading-with-pav/entry"}},"headers":[],"relativePath":"trading-with-pav/targets.md","filePath":"trading-with-pav/targets.md"}'),c={name:"trading-with-pav/targets.md"};function m(g,e,f,u,w,y){const a=t("GraphComment"),r=t("ClientOnly");return n(),s("div",null,[e[0]||(e[0]=l('<h1 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h1><p>In the last article we learned to place SL in this article will learn about Targets.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#targets-1">Targets</a></li><li><a href="#multiple-part-positions">Multiple Part Positions</a></li><li><a href="#identifying-price-targets">Identifying Price Targets</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="targets-1" tabindex="-1">Targets <a class="header-anchor" href="#targets-1" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><ul><li>At this point, price is in a setup area &amp; we have identified a potential stop location, a point to which price should NOT go.</li><li>We now aim to identify targets, should price trigger an entry.</li><li>Note that we do not wait for an entry, and then just simply target a reward 2 times our risk.</li><li>Many people recommend simply placing a target such that it achieves a 1:2 risk:reward ratio, or even a 1:3 risk:reward ratio, and then simply walking away until price hits one or the other.</li><li>Absolute rubbish, in my opinion!</li><li>This amateur technique affords no consideration for where orderflow is expected to oppose future price action (ie. areas of support or resistance providing barriers to price movement).</li><li>And it fails to consider the fact that the market sentiment is constantly changing, and the premise they used for entry may not persist long beyond their entry.</li><li>With our better understanding of the nature of markets and price movement, we will identify potential price targets based upon these areas of S/R.</li></ul><h2 id="multiple-part-positions" tabindex="-1">Multiple Part Positions <a class="header-anchor" href="#multiple-part-positions" aria-label="Permalink to &quot;Multiple Part Positions&quot;">​</a></h2><ul><li>Always prefer to trade in two part positions.</li><li>Part 1 will always operate with a price target, T1.</li><li>Part 2 will have a tentative target, T2.</li><li>However this part of the position may be allowed to run beyond T2,</li><li>if price action shows the potential for a trending move.</li><li>We will discuss more on this when we talk about <a href="/sk/trading-with-pav/trade-management/">trade management</a>.</li><li>For now, let’s just identify two targets, T1 &amp; T2.</li></ul><h2 id="identifying-price-targets" tabindex="-1">Identifying Price Targets <a class="header-anchor" href="#identifying-price-targets" aria-label="Permalink to &quot;Identifying Price Targets&quot;">​</a></h2><p><img src="'+p+'" alt="Targets-01-Chart"></p><p>PB Stop Placement</p><ul><li>The above chart shows the same example from our previous article of SL Placement and lets discuss targets for this trade.</li><li>Our ultimate aim is to trade the swings on the trading timeframe chart, so we use it for defining our targets. Once again though, the lower timeframe may be used for fine-tuning if necessary.</li><li>The first price target T1 will be the next level which is expected to provide opposing orderflow.</li><li>The second target T2 will be just prior to the next level of higher timeframe S/R. If price is at all-time highs or lows (or at least long time highs or lows), and so offers no real “next level” of S/R, I will target the first area of trading timeframe price stall beyond T1, or allow the price to simply trend with a trailing stop (an example follows shortly).</li></ul><p><img src="'+d+'" alt="Targets-02-Chart"></p><p>PB Targets</p><ul><li>Let’s look back at some of our setup charts in order to identify appropriate targets.</li><li>Again though, remember that we don’t simply set our stops and targets and then walk away. These are just initial areas we expect price to reach, based on our expectations for future price action. We’ll be actively managing the trade and may take profits earlier if our expectations change and our premise is no longer believed valid.</li><li>In figure above we show a PB setup, with T1 identified at 531, just short of potential swing high resistance, and T2 identified at 534.50, just below the next resistance level. This is clearly (with the benefit of hindsight) one example which would have benefited from running part 2 rather than targeting T2.</li><li>Next is T3 Swing Low at 539.40 which will be next opposing order-flow i.e. resistance.</li></ul><p>As you’ve seen, assigning targets is a simple process.</p><ul><li>T1 is the next trading timeframe (2 min) area expected to provide opposing order-flow (swing H/L, S/R level).</li><li>T2 is the area of higher timeframe (15 min) S/R beyond T1, although much more flexibility is afforded with T2 and you can adjust it closer if you wish, or trail beyond it for (hopefully) greater profits.</li><li>Same with T3.</li></ul><p>Will discuss how this trade goes after we learn about Entry in next article.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',18)),i(r,null,{default:h(()=>[i(a)]),_:1})])}const v=o(c,[["render",m]]);export{T as __pageData,v as default};
